<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, BookOpen, Check, ChevronLeft, Clock3, Code2, MessageCircle, RotateCcw, Sparkles, Target } from '@lucide/vue'

type Question = { type: '选择题' | '简答题' | '代码题'; title: string; options?: string[]; correct?: number; score: number; hint: string }
const router = useRouter(); const active = ref<number | null>(null); const questionIndex = ref(0); const answer = ref(''); const submitted = ref(false); const completed = ref(false)
const sets = [{ title: 'Transformer 基础', desc: '注意力机制、位置编码与编码器结构', meta: '3 题 · 预计 15 分钟', topic: 'Transformer' }, { title: '矩阵运算专项', desc: '矩阵乘法、向量空间与梯度计算', meta: '5 题 · 预计 25 分钟', topic: '矩阵运算' }]
const questions: Question[] = [{ type: '选择题', title: 'Transformer 中的自注意力机制主要解决什么问题？', options: ['让模型可以并行处理序列中的不同位置', '减少模型中的所有参数', '只关注输入序列的最后一个词', '将文本转换为图像'], correct: 0, score: 8, hint: '思考：注意力机制如何让序列中的位置彼此建立联系？' }, { type: '简答题', title: '为什么训练集准确率很高，但验证集准确率较低？请给出至少两种解决方案。', score: 8, hint: '可以从模型容量、数据量和正则化角度思考。' }, { type: '代码题', title: '用 PyTorch 实现一个包含卷积层与池化层的简单 CNN。', score: 10, hint: '使用 nn.Conv2d 与 nn.MaxPool2d。' }]
const currentSet = computed(() => sets[active.value ?? 0] || sets[0]!); const currentQuestion = computed(() => questions[questionIndex.value]!); const selectedOption = computed(() => answer.value.startsWith('option:') ? Number(answer.value.slice(7)) : null)
const start = (index: number) => { active.value = index; questionIndex.value = 0; answer.value = ''; submitted.value = false }
const submit = () => { submitted.value = true }
const next = () => { if (questionIndex.value < questions.length - 1) { questionIndex.value++; answer.value = ''; submitted.value = false } else { active.value = null; completed.value = true } }
const finish = () => { completed.value = true; active.value = null }
const choose = (index: number) => { if (!submitted.value) answer.value = selectedOption.value === index ? '' : `option:${index}` }
</script>

<template>
  <section class="exercise-page"><div class="exercise-inner">
    <header class="exercise-header"><div><span class="eyebrow">用练习确认真正掌握的知识</span><h1>练习中心</h1><p>根据你的知识图谱和学习画像，整理出适合当前阶段的练习。</p></div><button class="generate-button" @click="router.push('/question-nav-chat')"><Sparkles :size="16" />去对话页出题</button></header>
    <div v-if="active === null && !completed" class="exercise-home"><section class="pending-section"><div class="section-head"><div><h2>待完成练习</h2><span>完成后会同步更新知识图谱与学情分析</span></div><button class="text-action"><RotateCcw :size="14" />刷新</button></div><div class="exercise-list"><button v-for="(set,index) in sets" :key="set.title" class="exercise-row" @click="start(index)"><span class="exercise-icon"><Target :size="20" /></span><span class="exercise-copy"><strong>{{ set.title }}</strong><small>{{ set.desc }}</small><small>{{ set.meta }}</small></span><span class="exercise-score">待完成 <ArrowRight :size="17" /></span></button></div></section><section class="history-section"><div class="section-head"><div><h2>已完成的练习</h2><span>最近一次练习记录</span></div><button class="text-action">查看全部 <ArrowRight :size="14" /></button></div><article class="history-row"><span class="history-check"><Check :size="15" /></span><div><strong>CNN 基础专项</strong><p>选择 ×2 + 简答 ×1 · 7月11日</p><small>掌握度：45% → 61%</small></div><b>23 / 26 分</b></article></section></div>
    <section v-else-if="active !== null && !completed" class="question-panel"><div class="question-top"><button class="text-action" @click="active=null"><ChevronLeft :size="16" />退出</button><span><BookOpen :size="14" /> {{ currentSet.title }} · 第 {{ questionIndex + 1 }}/3 题</span><span>{{ currentQuestion.type }} · {{ currentQuestion.score }} 分</span></div><div class="question-content"><span class="eyebrow">{{ currentQuestion.type }} · {{ currentQuestion.score }} 分</span><h2>{{ currentQuestion.title }}</h2><p class="hint">💡 提示：{{ currentQuestion.hint }}</p><div v-if="currentQuestion.type === '选择题'" class="options"><button v-for="(option,index) in currentQuestion.options" :key="option" :class="{ selected: selectedOption === index, correct: submitted && index === currentQuestion.correct, wrong: submitted && selectedOption === index && index !== currentQuestion.correct }" @click="choose(index)"><span>{{ String.fromCharCode(65 + index) }}</span>{{ option }}<Check v-if="submitted && index === currentQuestion.correct" :size="15" /></button></div><textarea v-else-if="currentQuestion.type === '简答题'" v-model="answer" class="answer-area" placeholder="写下你的回答..." :disabled="submitted" /><div v-else class="code-editor"><div class="code-head"><Code2 :size="14" /> main.py <button @click="answer=''">重置</button></div><textarea v-model="answer" class="code-area" :disabled="submitted" placeholder="class SimpleCNN(nn.Module):\n    # 在这里写你的代码" /></div><div v-if="submitted" class="feedback"><Check :size="17" /><div><strong>{{ currentQuestion.type === '选择题' && selectedOption === currentQuestion.correct ? '回答正确！' : 'AI 批改反馈' }}</strong><p>{{ currentQuestion.type === '选择题' ? '自注意力让模型能够同时关注序列中不同位置的信息。' : '识别出了主要问题，建议补充正则化与 Early Stopping 的说明。' }}</p><div class="feedback-actions"><button @click="router.push('/question-nav-chat')"><MessageCircle :size="14" />追问 AI</button><button @click="router.push('/resource-center')"><BookOpen :size="14" />查看相关资源</button></div></div></div><div class="question-actions"><button class="outline-action" @click="answer=''">跳过此题</button><button class="primary-action" @click="submitted ? next() : submit()">{{ submitted ? (questionIndex === questions.length - 1 ? '完成练习' : '下一题') : '提交答案' }} <ArrowRight :size="15" /></button></div><div class="question-nav"><button v-for="(_,index) in questions" :key="index" :class="{ current: index === questionIndex, answered: index < questionIndex || (index === questionIndex && submitted) }" @click="questionIndex=index;answer='';submitted=false">{{ index + 1 }}</button></div></div></section>
    <section v-else class="completion-panel"><div class="completion-icon"><Check :size="29" /></div><span class="eyebrow">练习完成</span><h2>这组练习完成得不错</h2><div class="score-circle"><strong>23</strong><span>/ 26</span></div><p>Transformer 专项掌握度已从 55% 提升到 72%。</p><div class="result-list"><span>第 1 题 · 选择 <b>✓ 8/8</b></span><span>第 2 题 · 简答 <b>⚠ 7/8</b></span><span>第 3 题 · 代码 <b>✓ 8/10</b></span></div><div class="completion-actions"><button class="primary-action" @click="completed=false;start(0)"><RotateCcw :size="15" />错题重练</button><button class="outline-action" @click="router.push('/resource-center')"><BookOpen :size="15" />学习相关资源</button><button class="text-action" @click="completed=false">返回练习中心</button></div></section>
  </div></section>
</template>

